{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Bambuterol, a dimethylcarbamate ester, has an oral bioavailability of about 10% in healthy adults, directly showing that carbamate-containing drugs can fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Physostigmine, a carbamate acetylcholinesterase inhibitor, has poor oral bioavailability in humans, supporting low F for the query's carbamate-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "BMS-187745, a highly polar ionizable molecule, had an absolute oral bioavailability of only 2.6% in healthy subjects; the query's permanent quaternary ammonium charge similarly limits membrane permeation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Agomelatine has an absolute oral bioavailability below 5% in humans, demonstrating that low F can occur even in relatively lipophilic small molecules and reinforcing the likelihood of low F for the charged query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Apocynin has poor oral bioavailability (<10%) in humans, supporting low F for small polar aromatic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Zileuton exhibits poor oral bioavailability in humans, further supporting that low F is common among small oral drugs with polar or ionizable features.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a permanently charged quaternary pyridinium dimethylcarbamate. Multiple high-transfer human bioavailability records for carbamates and polar/ionizable drugs show F below 20%, so the query is predicted to have low absolute oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the evidence.",
    "Fasted-state-specific data are not explicitly reported for most analogues; extrapolation assumes similar absorption behavior under fasting conditions.",
    "Some records report qualitative 'poor' bioavailability rather than exact F values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

